func combinationSum(_ candidates: [Int], _ target: Int) -> [[Int]] {
    let c = candidates.sorted()
    var result: [[Int]] = [], path: [Int] = []
    func dfs(_ start: Int, _ remaining: Int) {
        if remaining == 0 { result.append(path); return }
        for i in start..<c.count {
            if c[i] > remaining { break }
            path.append(c[i]); dfs(i, remaining - c[i]); path.removeLast()
        }
    }
    dfs(0, target)
    return result
}
